import{_ as i}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as o,c as s,o as t,af as r,b as d,w as n,a as l,G as h,ag as c}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const x=JSON.parse('{"title":"Group 4 · Grounding","description":"Model knowledge is frozen at training time—this group ties answers to your own evidence: a traceable retrieval chain and a re-runnable update pipeline.","frontmatter":{"title":"Group 4 · Grounding","description":"Model knowledge is frozen at training time—this group ties answers to your own evidence: a traceable retrieval chain and a re-runnable update pipeline.","domain":"tech","tags":["grounding","navigation"],"navOrder":40,"topicId":"grounding","layer":"4","status":"canonical","nodeType":"problem","owner":"learn-ai","externalOwners":[{"site":"llm","url":"https://llm.zenheart.site/chapters/11-rag"}],"prerequisites":["streaming"],"next":["embeddings-retrieval","rag","advanced-retrieval","tool-execution"],"lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"tech/04-grounding/index.md","filePath":"tech/04-grounding/index.md","lastUpdated":1791115887000}'),u={name:"tech/04-grounding/index.md"};function p(g,e,m,v,f,b){const a=o("Mermaid");return t(),s("div",null,[e[1]||(e[1]=r('<h1 id="group-4-·-grounding" tabindex="-1">Group 4 · Grounding <a class="header-anchor" href="#group-4-·-grounding" aria-label="Permalink to &quot;Group 4 · Grounding&quot;">​</a></h1><blockquote><p><strong>Group</strong>: 4 · Grounding (reading the world) | <strong>Previous group exit</strong>: write and validate input/output schemas, and deliver a cancellable, observable end-to-end interaction (groups 2–3) | <strong>This group exit</strong>: build a traceable retrieval chain and an update pipeline <strong>Prerequisites</strong>: <a href="./../02-inference-interface/streaming.html">Streaming</a> | <strong>Next</strong>: <a href="./embeddings-retrieval.html">Embeddings and Retrieval</a>, <a href="./../05-action/tool-execution.html">Tool Execution Engineering</a></p></blockquote><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>This group addresses one specific symptom: <strong>answers lack private or fresh facts</strong>. A model&#39;s parametric memory is frozen the moment training ends—it does not know your tickets, your code, or the document you changed last week. This group ties answers to external evidence: retrieve first, generate second, attach provenance to every answer, and rebuild when the data changes.</p><p>The original RAG paper (Lewis et al., NeurIPS 2020) named this structure &quot;parametric memory + non-parametric memory&quot;: the parametric memory is a pre-trained generator, the non-parametric memory is an external vector index accessed by a retriever (in the paper, a dense vector index of Wikipedia). The paper also states that for pure parametric models, &quot;providing provenance for their decisions&quot; and &quot;updating their world knowledge&quot; remain open problems—exactly the two things this group delivers (a traceable retrieval chain, a re-runnable update pipeline) (arXiv:2005.11401, abstract re-verified, retrievedAt 2026-09-01).</p><p>This group shares the intuition of letting the model touch things outside itself with the <a href="./../05-action/tool-calling.html">Action group</a> (05), but the direction is opposite: <strong>reading the world vs. writing the world</strong>. Everything here is a read—chunking, indexing, retrieving, citing—with no side effects by default; the failure mode is &quot;wrong answer&quot; or &quot;should have refused but didn&#39;t&quot;, never destruction. The Action group writes to the world (executing actions); its failure mode is &quot;broken state&quot;. Hence the different acceptance criteria: this group audits <strong>citation correctness and refusal correctness</strong>; the Action group audits <strong>restricted permissions and recoverability</strong>.</p>',6)),(t(),d(c,null,{default:n(()=>[h(a,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20offline%5B%22Offline%3A%20update%20pipeline%22%5D%0A%20%20%20%20%20%20%20%20A%5BCorpus%5D%20--%3E%20B%5BChunk%5D%20--%3E%20C%5BEmbed%5D%20--%3E%20D%5B(Index%3A%20text%20%2B%20vectors%20%2B%20metadata)%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20online%5B%22Online%3A%20retrieval%20chain%22%5D%0A%20%20%20%20%20%20%20%20Q%5BUser%20question%5D%20--%3E%20E%5BRetrieve%20top-k%5D%20--%3E%20F%5BFilter%3A%20permissions%2Ftenant%5D%20--%3E%20G%5BRerank%5D%20--%3E%20H%5BGenerate%3A%20answer%20must%20cite%5D%0A%20%20%20%20%20%20%20%20E%20--%3E%7Cno%20hit%7C%20R%5BRefuse%3A%20rather%20say%20no%5D%0A%20%20%20%20end%0A%20%20%20%20D%20--%3E%20E%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r(`<h3 id="when-to-enter-this-group-when-not-to" tabindex="-1">When to enter this group / when not to <a class="header-anchor" href="#when-to-enter-this-group-when-not-to" aria-label="Permalink to &quot;When to enter this group / when not to&quot;">​</a></h3><ul><li><strong>Enter</strong>: answers need private corpora (product docs, tickets, code), need citations, or the knowledge updates frequently.</li><li><strong>Do not enter</strong>: answers are unstable or unparseable—go back to <a href="./../03-context/">Group 3 Context</a> (the output-shape landing point: <a href="./../02-inference-interface/structured-output.html">structured output</a>); not yet wired into a product interaction—start <a href="./../02-inference-interface/">Group 2 Inference &amp; Interface</a>; you need the system to take actions—go to <a href="./../05-action/tool-calling.html">Group 5 Action</a>.</li></ul><h3 id="symptom-→-topic-navigation" tabindex="-1">Symptom → topic navigation <a class="header-anchor" href="#symptom-→-topic-navigation" aria-label="Permalink to &quot;Symptom → topic navigation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symptom</th><th>Go to</th><th>After reading you can</th></tr></thead><tbody><tr><td>Want search by meaning; keywords miss</td><td><a href="./embeddings-retrieval.html">Embeddings and Retrieval</a></td><td>Build a vector retrieval entry with metadata filtering and a no-hit path</td></tr><tr><td>Building &quot;answer from our docs&quot; features</td><td><a href="./rag.html">RAG: Retrieval-Augmented Generation</a></td><td>Run the full ingest→chunk→embed→retrieve→generate chain with citations and refusals</td></tr><tr><td>Baseline RAG recall not enough / error codes not found</td><td><a href="./advanced-retrieval.html">Advanced Retrieval</a></td><td>Raise recall with hybrid search, query rewriting, reranking; pin permissions at the retrieval layer</td></tr></tbody></table><h3 id="decision-table-knowledge-injection-options" tabindex="-1">Decision table: knowledge injection options <a class="header-anchor" href="#decision-table-knowledge-injection-options" aria-label="Permalink to &quot;Decision table: knowledge injection options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>Direction</th><th>Control</th><th>State</th><th>Trust domain</th><th>Minimum complexity</th></tr></thead><tbody><tr><td>Long-context stuffing</td><td>Corpus → prompt (bulk move)</td><td>Prompt-layer concat, no retrieval control</td><td>Full text resent per request</td><td>Entire corpus enters model context</td><td>Lowest (small single-batch corpus)</td></tr><tr><td>RAG (this group)</td><td>Query → retrieve → context (selective move)</td><td>Index, chunking, filtering all yours</td><td>Index is derived, rebuildable</td><td>Only hit fragments reach the model</td><td>Medium (embedding + index + pipeline)</td></tr><tr><td>Fine-tuning</td><td>Corpus → parameters (rewrite the model)</td><td>Training recipe and data mix</td><td>Baked into weights; update = retrain</td><td>Corpus enters the training pipeline</td><td>Highest (see Learn LLM bridge)</td></tr></tbody></table><p>Selection principle: <strong>start at the lowest complexity</strong>. If a batch of corpus fits in the context (Anthropic&#39;s reference line is about 200,000 tokens, with prompt caching), stuff it first; move to RAG when the corpus is large, updates often, or citations matter; consider fine-tuning only to change behavior style, not facts.</p><h3 id="historical-milestones" tabindex="-1">Historical milestones <a class="header-anchor" href="#historical-milestones" aria-label="Permalink to &quot;Historical milestones&quot;">​</a></h3><ul><li>2016: HNSW approximate nearest-neighbor index published (Malkov &amp; Yashunin, arXiv:1603.09320); became the mainstream index foundation of vector databases (retrievedAt 2026-09-01).</li><li>2020: RAG paper published (Lewis et al., NeurIPS 2020, arXiv:2005.11401), establishing the &quot;parametric + non-parametric memory&quot; framing (retrievedAt 2026-09-01).</li><li>2024-09-19: Anthropic published Contextual Retrieval (contextualized chunks + BM25 + reranking); experiment data in <a href="./advanced-retrieval.html">Advanced Retrieval</a>. The publish date was cross-checked against multiple independent secondary sources (retrievedAt 2026-09-01).</li><li>2026-09: the v6 restructure (Issue #116) replaced the v5 six-layer pyramid with ten dependency-ordered groups; this group went from &quot;Layer 3 · Knowledge Grounding&quot; to &quot;Group 4 · Grounding (reading the world)&quot;. The read/write boundary and acceptance criteria are unchanged.</li></ul><h2 id="_2-usage" tabindex="-1">2. Usage <a class="header-anchor" href="#_2-usage" aria-label="Permalink to &quot;2. Usage&quot;">​</a></h2><p>This group&#39;s minimal hands-on is the zero-key example in <a href="./embeddings-retrieval.html">Embeddings and Retrieval</a>: a pure-TypeScript deterministic vector retriever that runs in a clean environment within 15 minutes.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Save the full example from the embeddings-retrieval page as embeddings-retrieval.ts, then:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> embeddings-retrieval.ts</span></span></code></pre></div><p>Acceptance: three output groups present—a lexically overlapping query hits the right document with its source; a paraphrased query (zero lexical overlap) correctly takes the no-hit path; an off-corpus question correctly refuses. Once it runs you have seen this group&#39;s two core behaviors: <strong>a score is not truth</strong> (high similarity only means &quot;similar&quot;), and <strong>no-hit is a path, not an exception</strong>.</p><p>Every topic&#39;s Usage section follows the same constraints: zero API keys, single self-contained file, deterministic output, positive and negative paths in pairs.</p><h2 id="_3-principles" tabindex="-1">3. Principles <a class="header-anchor" href="#_3-principles" aria-label="Permalink to &quot;3. Principles&quot;">​</a></h2><p>On the capability chain, this group upgrades Group 2&#39;s &quot;one interaction&quot; into &quot;one grounded interaction&quot;:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Offline: corpus → chunk → embed → index (text + vectors + metadata + content fingerprint)</span></span>
<span class="line"><span>Online:  question → retrieve top-k → filter (permissions/tenant) → rerank → generate (with citations)</span></span>
<span class="line"><span>Update:  document change → fingerprint compare → incrementally rebuild entries → delete stale ones</span></span></code></pre></div><ul><li><strong>Invariant 1: cite, or say there is nothing</strong>. Every answer must trace back to a source document; if retrieval finds nothing, refuse—never let the model fill the gap from parametric memory.</li><li><strong>Invariant 2: permission filtering happens at retrieval time</strong>. Documents a user cannot see must not be retrievable by them; filtering happens during recall, not by hiding after generation.</li><li><strong>Invariant 3: the index is a derived artifact</strong>. It is determined by &quot;corpus + chunking strategy + embedding model version&quot;; any change requires a rebuild; the index can always be re-derived from the corpus.</li></ul><p><strong>Exit criteria</strong>: build a traceable retrieval chain and an update pipeline—any answer traces back to its source document and chunk; questions that should be refused are refused; after corpus updates, a re-runnable rebuild pipeline exists.</p><p>Per-topic details: <a href="./embeddings-retrieval.html">embeddings-retrieval</a>, <a href="./rag.html">rag</a>, <a href="./advanced-retrieval.html">advanced-retrieval</a>.</p><h2 id="_4-development" tabindex="-1">4. Development <a class="header-anchor" href="#_4-development" aria-label="Permalink to &quot;4. Development&quot;">​</a></h2><p>Before entering the layer, use three diagnostics to locate the right page.</p><h3 id="symptom-→-evidence-→-action-→-done-when" tabindex="-1">Symptom → Evidence → Action → Done when <a class="header-anchor" href="#symptom-→-evidence-→-action-→-done-when" aria-label="Permalink to &quot;Symptom → Evidence → Action → Done when&quot;">​</a></h3><p><strong>Symptom</strong>: the model fabricates private facts, confidently. <strong>Evidence</strong>: ask the same question to the bare model and to the retrieval-backed product; check retrieval logs for hits. <strong>Action</strong>: confirm the question actually goes through the retrieval chain; add no-hit refusal and citation constraints per <a href="./rag.html">rag</a>. <strong>Done when</strong>: every &quot;should refuse&quot; item in the golden set is refused; every &quot;should hit&quot; answer carries a correct citation.</p><h3 id="symptom-→-evidence-→-action-→-done-when-1" tabindex="-1">Symptom → Evidence → Action → Done when <a class="header-anchor" href="#symptom-→-evidence-→-action-→-done-when-1" aria-label="Permalink to &quot;Symptom → Evidence → Action → Done when&quot;">​</a></h3><p><strong>Symptom</strong>: the answer cites a passage that does not match what it says. <strong>Evidence</strong>: replay sampled answers against the text their chunk ids point to; check whether chunk boundaries cut semantics apart. <strong>Action</strong>: re-chunk per <a href="./embeddings-retrieval.html">embeddings-retrieval</a> (structure-first boundaries, with overlap); rebuild the index with stable ids. <strong>Done when</strong>: 20 sampled answers all cite passages that support them.</p><h3 id="symptom-→-evidence-→-action-→-done-when-2" tabindex="-1">Symptom → Evidence → Action → Done when <a class="header-anchor" href="#symptom-→-evidence-→-action-→-done-when-2" aria-label="Permalink to &quot;Symptom → Evidence → Action → Done when&quot;">​</a></h3><p><strong>Symptom</strong>: the document changed; the answer still gives the old version. <strong>Evidence</strong>: compare index entry timestamps/content fingerprints against the current document version. <strong>Action</strong>: fix the indexing pipeline per <a href="./rag.html">rag</a> (content fingerprint + incremental rebuild + stale-entry deletion). <strong>Done when</strong>: after the rebuild triggered by the document update, the same question&#39;s answer points to the new version.</p><h2 id="_5-resource-library" tabindex="-1">5. Resource Library <a class="header-anchor" href="#_5-resource-library" aria-label="Permalink to &quot;5. Resource Library&quot;">​</a></h2><h3 id="four-level-reading-route" tabindex="-1">Four-level reading route <a class="header-anchor" href="#four-level-reading-route" aria-label="Permalink to &quot;Four-level reading route&quot;">​</a></h3><ul><li><strong>Beginner</strong>: <a href="./embeddings-retrieval.html">Embeddings and Retrieval</a> (run one vector search first).</li><li><strong>Builder</strong>: <a href="./rag.html">RAG: Retrieval-Augmented Generation</a> (wire retrieval into the generation loop).</li><li><strong>Operator</strong>: runbooks in each topic&#39;s Development section → <a href="./../08-production/evaluation.html">Evaluation (bridge)</a> (turn citation correctness into a release gate).</li><li><strong>Researcher</strong>: <a href="./advanced-retrieval.html">Advanced Retrieval</a> → Learn LLM&#39;s RAG chapters (mechanisms and math, not duplicated here).</li></ul><h3 id="active-falsification-and-open-questions" tabindex="-1">Active falsification and open questions <a class="header-anchor" href="#active-falsification-and-open-questions" aria-label="Permalink to &quot;Active falsification and open questions&quot;">​</a></h3><ul><li>&quot;About 200,000 tokens fits by stuffing&quot; comes from the Anthropic Contextual Retrieval post (retrievedAt 2026-09-01); actual windows and cache prices change—recheck the official docs on the day you use them.</li><li>The hybrid-search and reranking gains are Anthropic&#39;s experimental results on their corpus and configuration; run your own golden-set comparison before porting the numbers.</li></ul><h3 id="where-learn-ai-stops-where-to-go-next" tabindex="-1">Where learn-ai stops / where to go next <a class="header-anchor" href="#where-learn-ai-stops-where-to-go-next" aria-label="Permalink to &quot;Where learn-ai stops / where to go next&quot;">​</a></h3><p>This group answers &quot;how to ground results&quot;. It does not answer &quot;embedding training objectives and vector geometry&quot; (→ <a href="https://llm.zenheart.site/chapters/11-rag" target="_blank" rel="noreferrer">Learn LLM</a>), &quot;evaluation methodology and benchmarks&quot; (→ <a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">evals</a>), or &quot;executing actions and permissions&quot; (→ <a href="./../05-action/tool-calling.html">Group 5 Action</a>).</p>`,35))])}const A=i(u,[["render",p]]);export{x as __pageData,A as default};
